commands.command:
sudo -u postgres psql -v ON_ERROR_STOP=1 -d helpdesk <<'SQL'
BEGIN;
INSERT INTO tickets(subject) VALUES ('Sequence allocation verification') RETURNING id, subject;
ROLLBACK;
SELECT setval(pg_get_serial_sequence('tickets','id'), (SELECT max(id) FROM tickets), true) AS restored_sequence_value;
SELECT id, subject FROM tickets ORDER BY id;
SELECT (SELECT max(id) FROM tickets) AS imported_max, last_value AS sequence_value, is_called FROM tickets_id_seq;
SQL
sha256sum /srv/legacy2/postgresql-sequence-repair/tickets.sql
ls -l /srv/legacy2/postgresql-sequence-repair/tickets.sql

printf 'PRE_RESTART_BOOT_ID='; cat /proc/sys/kernel/random/boot_id; printf 'OS_KERNEL='; lsb_release -ds 2>/dev/null; uname -r; printf 'POSTGRES_CLUSTER\n'; pg_lsclusters; printf 'POSTGRES_PACKAGE='; dpkg-query -W -f='${Version}\n' postgresql-8.2; printf 'HELPDESK_DATA_AND_SEQUENCE\n'; sudo -u postgres psql -v ON_ERROR_STOP=1 -d helpdesk <<'SQL'
SELECT id, subject FROM tickets ORDER BY id;
SELECT max(id) AS imported_max FROM tickets;
SELECT last_value, is_called FROM tickets_id_seq;
SQL
printf 'SOURCE_EXPORT\n'; sha256sum /srv/legacy2/postgresql-sequence-repair/tickets.sql; ls -l /srv/legacy2/postgresql-sequence-repair/tickets.sql

printf 'POST_RESTART_BOOT_ID='; cat /proc/sys/kernel/random/boot_id; printf 'OS_KERNEL='; lsb_release -ds 2>/dev/null; uname -r; printf 'POSTGRES_CLUSTER\n'; pg_lsclusters; printf 'HELPDESK_RECOVERY_AND_ALLOCATION\n'; sudo -u postgres psql -v ON_ERROR_STOP=1 -d helpdesk <<'SQL'
SELECT id, subject FROM tickets ORDER BY id;
SELECT max(id) AS imported_max FROM tickets;
SELECT last_value, is_called FROM tickets_id_seq;
BEGIN;
INSERT INTO tickets(subject) VALUES ('Post-restart allocation verification') RETURNING id, subject;
ROLLBACK;
SELECT setval(pg_get_serial_sequence('tickets','id'), (SELECT max(id) FROM tickets), true) AS restored_sequence_value;
SELECT count(*) AS final_ticket_count, min(id) AS min_id, max(id) AS max_id FROM tickets;
SELECT last_value, is_called FROM tickets_id_seq;
SQL
printf 'SOURCE_EXPORT\n'; sha256sum /srv/legacy2/postgresql-sequence-repair/tickets.sql; ls -l /srv/legacy2/postgresql-sequence-repair/tickets.sql
